import{_ as n,c as s,b as a,o as i}from"./app-Di-e0zxZ.js";const l={};function t(r,e){return i(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="类型体操-实习" tabindex="-1"><a class="header-anchor" href="#类型体操-实习"><span>类型体操-实习</span></a></h1><p>在正式开始做类型体操前，请阅读这篇文章 <a href="https://juejin" target="_blank" rel="noopener noreferrer">https://juejin</a>.cn/post/7616265766073221130</p><ul><li><p><strong>条件类型</strong> <code>T extends U ? A : B</code> —— 分支判断</p></li><li><p><strong>映射类型</strong> <code>{ [K in keyof T]: ... }</code> —— 遍历 + 变换</p></li><li><p><strong>递归</strong> —— 处理嵌套结构</p></li><li><p><strong>模板字面量类型</strong> —— 字符串拼接</p></li><li><p><strong>infer</strong> —— 模式匹配提取</p></li></ul><h1 id="remove-index-signature-删除索引签名" tabindex="-1"><a class="header-anchor" href="#remove-index-signature-删除索引签名"><span>Remove Index Signature 删除索引签名</span></a></h1><p>Implement RemoveIndexSignature&amp;lt;T&amp;gt; , exclude the index signature from object types.实现从对象类型中排除索引签名。 例如:</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">type Foo = {[key: string]: anyfoo(): void}type A = RemoveIndexSignature&lt;Foo&gt; </span>
<span class="line">// expected { foo(): void }</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>答案：</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">type RemoveIndexSignature&lt;T&gt; = {</span>
<span class="line">  [K in keyof T as/* filters out all &#39;string&#39; keys */</span>
<span class="line">    string extends K</span>
<span class="line">      ? never/* filters out all &#39;number&#39; keys */</span>
<span class="line">      : number extends K</span>
<span class="line">        ? never/* filers out all &#39;symbol&#39; keys */</span>
<span class="line">        : symbol extends K</span>
<span class="line">          ? never </span>
<span class="line">          : K /* all that&#39;s left are literal type keys */</span>
<span class="line">   ]: T[K]</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这个方案通过检查键是否是通用类型（<code>string</code>、<code>number</code>、<code>symbol</code>）的超类型来过滤掉索引签名</p><p>索引签名的设计目的是为了处理在编译时未知的属性访问。它的语义是&quot;当使用任意字符串/数字/符号作为键访问对象时，返回值的类型是什么&quot;。因此它必须使用通用类型，而非具体的字面量类型。#</p><h1 id="percentage-parser" tabindex="-1"><a class="header-anchor" href="#percentage-parser"><span>Percentage Parser</span></a></h1><p>实现类型 PercentageParser。根据规则 <code>/^(\\+|\\-)?(\\d*)?(\\%)?$/</code> 匹配类型 T。</p><p>匹配的结果由三部分组成，分别是：[<code>正负号</code>, <code>数字</code>, <code>单位</code>]，如果没有匹配，则默认是空字符串。</p><p>例如：</p><div class="language-Python line-numbers-mode" data-highlighter="prismjs" data-ext="Python"><pre><code class="language-Python"><span class="line">type PString1 = &#39;&#39;</span>
<span class="line">type PString2 = &#39;+85%&#39;</span>
<span class="line">type PString3 = &#39;-85%&#39;</span>
<span class="line">type PString4 = &#39;85%&#39;</span>
<span class="line">type PString5 = &#39;85&#39;</span>
<span class="line"></span>
<span class="line">type R1 = PercentageParser&lt;PString1&gt; // expected [&#39;&#39;, &#39;&#39;, &#39;&#39;]</span>
<span class="line">type R2 = PercentageParser&lt;PString2&gt; // expected [&quot;+&quot;, &quot;85&quot;, &quot;%&quot;]</span>
<span class="line">type R3 = PercentageParser&lt;PString3&gt; // expected [&quot;-&quot;, &quot;85&quot;, &quot;%&quot;]</span>
<span class="line">type R4 = PercentageParser&lt;PString4&gt; // expected [&quot;&quot;, &quot;85&quot;, &quot;%&quot;]</span>
<span class="line">type R5 = PercentageParser&lt;PString5&gt; // expected [&quot;&quot;, &quot;85&quot;, &quot;&quot;]</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>答案：</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">type PercentageParser&lt;A extends string&gt; = </span>
<span class="line">A extends \`\${infer O extends &#39;+&#39; | &#39;-&#39;}\${infer N}%\` </span>
<span class="line">    ? [O, N, &#39;%&#39;]</span>
<span class="line">    : A extends \`\${infer O extends &#39;+&#39; | &#39;-&#39;}\${infer N}\`</span>
<span class="line">        ? [O, N, &#39;&#39;]</span>
<span class="line">        : A extends \`\${infer N}%\`</span>
<span class="line">            ? [N, &#39;%&#39;]</span>
<span class="line">            : A extends \`\${infer N}\`</span>
<span class="line">                ? [&#39;&#39;, N, &#39;&#39;]</span>
<span class="line">                : never </span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这里的答案并不能通过全部的测试，不过一般情况也不会去写这种类型吧</p><h1 id="drop-char" tabindex="-1"><a class="header-anchor" href="#drop-char"><span>Drop Char</span></a></h1><p>从字符串中剔除指定字符。</p><p>例如：</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">type Butterfly = DropChar&lt;&#39; b u t t e r f l y ! &#39;, &#39; &#39;&gt; // &#39;butterfly!&#39;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>答案：</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">type DropChar&lt;S, C extends string&gt; = </span>
<span class="line">    S extends \`\${infer F}\${C}\${infer R}\` </span>
<span class="line">        ? DropChar&lt;\`\${F}\${R}\`, C&gt; </span>
<span class="line">        : S </span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>使用递归的方式将字符剔除。最开始F为&#39;&#39;， C为&#39; &#39;，R为&#39; u t t e r f l y ! &#39;，继承。将第一个&#39; &#39;剔除，剩余的&#39;b u t t e r f l y ! &#39;再次传入DropChar，此时F为&#39;b&#39;， C为&#39; &#39;，R为&#39;u t t e r f l y ! &#39;。</p><h1 id="pickbytype" tabindex="-1"><a class="header-anchor" href="#pickbytype"><span>PickByType</span></a></h1><p>From <code>T</code>, pick a set of properties whose type is assignable to <code>U</code>.从T中将能够赋值给U的属性选出</p><p>For Example:</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">type OnlyBoolean = PickByType&lt;{</span>
<span class="line">  name: string</span>
<span class="line">  count: number</span>
<span class="line">  isReadonly: boolean</span>
<span class="line">  isEnable: boolean</span>
<span class="line">}, boolean&gt; // { isReadonly: boolean; isEnable: boolean; }</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Answer:</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">type PickByType&lt;T, U&gt; = {</span>
<span class="line">  // 筛选符合要求的key，再映射</span>
<span class="line">  [K in keyof T as T[K] extends U ? K : never] : T[K]</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>在 TypeScript 的映射类型（Mapped Types）中，<code>as</code> 关键字用于<strong>重命名或过滤键（Key）</strong>。</p><p>在你提供的代码片段中：</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">[K in keyof T as T[K] extends U ? K : never]</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>这里的 <code>as</code> 具体起到了过滤的作用。</p><ol><li><strong>基本语法</strong>： 在 TypeScript 4.1+ 版本引入的映射类型语法中，结构通常是：</li></ol><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">{ [K in Keys] : Type } // 旧写法，只能遍历</span>
<span class="line">{ [K in Keys as NewKey] : Type } // 新写法，可以重命名或排除</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><ol><li><p><code>as</code> 后面的表达式决定了最终对象中保留哪些键，以及这些键叫什么名字。</p></li><li><p><strong>在你的代码中的逻辑</strong>：</p><ul><li><p><code>K in keyof T</code>：遍历类型 <code>T</code> 的所有键。</p></li><li><p><code>as</code>：对当前的键 <code>K</code> 进行转换判断。</p></li><li><p><code>T[K] extends U ? K : never</code>：这是一个条件类型。</p><ul><li><p>如果 <code>T</code> 中键 <code>K</code> 对应的值类型 <code>T[K]</code> assignable to (可赋值给) <code>U</code>，则结果为 <code>K</code>（保留原键名）。</p></li><li><p>否则，结果为 <code>never</code>。</p></li></ul></li></ul></li><li><p><strong><code>never</code></strong>** 的特殊行为**： 在映射类型的 <code>as</code> 子句中，如果计算结果是 <code>never</code>，TypeScript 会<strong>直接从结果类型中剔除该键</strong>。TS 的映射类型里，如果把某个 key 映射到 <code>never</code>，它就会被自动移除。</p></li></ol><h1 id="mutable" tabindex="-1"><a class="header-anchor" href="#mutable"><span>Mutable</span></a></h1><p>实现一个通用的类型 <code>Mutable&amp;lt;T&amp;gt;</code>，使类型 <code>T</code> 的全部属性可变（非只读）。</p><p>例如：</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">interface Todo {</span>
<span class="line">  readonly title: string</span>
<span class="line">  readonly description: string</span>
<span class="line">  readonly completed: boolean</span>
<span class="line">}</span>
<span class="line"></span>
<span class="line">// { title: string; description: string; completed: boolean; }</span>
<span class="line">type MutableTodo = Mutable&lt;Todo&gt; </span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>答案：</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">type Mutable&lt;T&gt; = {</span>
<span class="line">  - readonly [key in  keyof T]:T[key]</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>官方文档 <a href="https://www" target="_blank" rel="noopener noreferrer">https://www</a>.typescriptlang.org/docs/handbook/2/mapped-types.html#mapping-modifiers</p><h1 id="omitbytype" tabindex="-1"><a class="header-anchor" href="#omitbytype"><span>OmitByType</span></a></h1><p>From <code>T</code>, pick a set of properties whose type are not assignable to <code>U</code>.</p><p>For Example</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">type OmitBoolean = OmitByType&lt;</span>
<span class="line">    {name: stringcount: numberisReadonly: booleanisEnable: boolean}, </span>
<span class="line">boolean&gt; // { name: string; count: number }</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>答案：</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">type OmitByType&lt;T, U&gt; = {</span>
<span class="line">  [key in keyof T as T[key] extends U ? never : key] : T[key]</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>和<code>PickByType</code>很像</p><h1 id="objectentries" tabindex="-1"><a class="header-anchor" href="#objectentries"><span>ObjectEntries</span></a></h1><p>Implement the type version of <code>Object.entries</code></p><p>For example</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">interface Model {</span>
<span class="line">  name: string;</span>
<span class="line">  age: number;</span>
<span class="line">  locations: string[] | null;</span>
<span class="line">}</span>
<span class="line">type modelEntries = ObjectEntries&lt;Model&gt; </span>
<span class="line">// [&#39;name&#39;, string] | [&#39;age&#39;, number] | [&#39;locations&#39;, string[] | null];</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>答案：</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">type ObjectEntries&lt;T&gt; = {</span>
<span class="line">  [K in keyof T]-?: [K, T[K]]</span>
<span class="line">}[keyof T]</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这里去掉可选是因为 <a href="https://github" target="_blank" rel="noopener noreferrer">https://github</a>.com/type-challenges/type-challenges/issues/14052</p><h1 id="reverse" tabindex="-1"><a class="header-anchor" href="#reverse"><span>Reverse</span></a></h1><p>和<code>Array.reverse()</code>一样</p><p>例子：</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">type a = Reverse&lt;[&#39;a&#39;, &#39;b&#39;]&gt; </span>
<span class="line">// [&#39;b&#39;, &#39;a&#39;]</span>
<span class="line"></span>
<span class="line">type b = Reverse&lt;[&#39;a&#39;, &#39;b&#39;, &#39;c&#39;]&gt; </span>
<span class="line">// [&#39;c&#39;, &#39;b&#39;, &#39;a&#39;]</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>答案：</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">// 将第一个放到最后</span>
<span class="line">type Reverse&lt;T extends any[]&gt; = </span>
<span class="line">    T extends [infer F, ...infer Rest] ? [...Reverse&lt;Rest&gt;, F] : T;</span>
<span class="line"></span>
<span class="line">// 反之，将最后一个放到前面来  </span>
<span class="line">type Reverse&lt;T extends any[]&gt; = </span>
<span class="line">    T extends [...infer rest, infer last] ? [last, ...Reverse&lt;rest&gt;] : T</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>思路是很典型的递归，每次将最后一个/第一个取出来，剩下的部分递归。</p><h1 id="fliparguments" tabindex="-1"><a class="header-anchor" href="#fliparguments"><span>FlipArguments</span></a></h1><p>答案：</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">type FlipArguments&lt;T extends (...args: any[]) =&gt; any&gt; = </span>
<span class="line">    T extends (...args: infer P) =&gt; infer U </span>
<span class="line">        ? (...args: Reverse&lt;P&gt;) =&gt; U</span>
<span class="line">        : never;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>使用Reverse&amp;lt;&amp;gt;将参数reverse一下。</p><h1 id="bem-style-string" tabindex="-1"><a class="header-anchor" href="#bem-style-string"><span>BEM style string</span></a></h1><p>The Block, Element, Modifier methodology (BEM) is a popular naming convention for classes in CSS.</p><p>For example, the block component would be represented as <code>btn</code>, element that depends upon the block would be represented as <code>btn__price</code>, modifier that changes the style of the block would be represented as <code>btn--big</code> or <code>btn__price--warning</code>.</p><p>Implement <code>BEM&amp;lt;B, E, M&amp;gt;</code> which generate string union from these three parameters. Where <code>B</code> is a string literal, <code>E</code> and <code>M</code> are string arrays (can be empty).</p><p>答案：</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">// 这里做了换行，是为了看的清楚，最好是写在一行里</span>
<span class="line">type BEM&lt;B extends string, E extends string[],M extends string[]&gt; = </span>
<span class="line">  \`</span>
<span class="line">    \${B}</span>
<span class="line">    \${E extends [] ? &#39;&#39; : \`__\${E[number]}\`}</span>
<span class="line">    \${M extends [] ? &#39;&#39; : \`--\${M[number]}\`}</span>
<span class="line">  \`</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>数组转联合类型用 <code>[number]</code> 作为下标</p><h1 id="flip" tabindex="-1"><a class="header-anchor" href="#flip"><span>Flip</span></a></h1><p>将对象的键与值对调</p><div class="language-YAML line-numbers-mode" data-highlighter="prismjs" data-ext="YAML"><pre><code class="language-YAML"><span class="line">Flip&lt;{ a: &quot;x&quot;, b: &quot;y&quot;, c: &quot;z&quot; }&gt;; // {x: &#39;a&#39;, y: &#39;b&#39;, z: &#39;c&#39;}</span>
<span class="line">Flip&lt;{ a: 1, b: 2, c: 3 }&gt;; // {1: &#39;a&#39;, 2: &#39;b&#39;, 3: &#39;c&#39;}</span>
<span class="line">Flip&lt;{ a: false, b: true }&gt;; // {false: &#39;a&#39;, true: &#39;b&#39;}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>答案：</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">// 这样写，会有几个测试过不了，需要优化</span>
<span class="line">type Flip&lt;T&gt; = {</span>
<span class="line">  [key in keyof T as T[key]] : key</span>
<span class="line">}</span>
<span class="line"></span>
<span class="line">// 优化后</span>
<span class="line">type Flip&lt;T extends Record&lt;string, string | number | boolean&gt;&gt; = {</span>
<span class="line">  [key in keyof T as \`\${T[key]}\`] : key</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>使用<code>Record</code>是因为测试中的几个例子键只能是<code>string</code>、<code>number</code>与<code>boolean</code>，然后<code>boolean</code>是不做键的，需要转成字符串</p><p><a href="https://github" target="_blank" rel="noopener noreferrer">https://github</a>.com/type-challenges/type-challenges/issues/14094</p><h1 id="zip" tabindex="-1"><a class="header-anchor" href="#zip"><span>Zip</span></a></h1><p>将两个元组合并成一个</p><p>In This Challenge, You should implement a type Zip&amp;lt;T, U&amp;gt;, T and U must be Tuple</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">type exp = Zip&lt;[1, 2], [true, false]&gt; // expected to be [[1, true], [2, false]]</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>答案：</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">type Zip&lt;T extends any[], U extends any[]&gt; = </span>
<span class="line">    [T, U] extends [[infer L, ...infer restL], [infer R, ...infer restR]] </span>
<span class="line">        ? [[L, R], ...Zip&lt;restL, restR&gt;] </span>
<span class="line">        : []</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这道题又是一个经典的递归，我最开始是使用映射类型来做的</p><h1 id="istuple" tabindex="-1"><a class="header-anchor" href="#istuple"><span>IsTuple</span></a></h1><p>判断一个类型是不是元组</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">type case1 = IsTuple&lt;[number]&gt; // true</span>
<span class="line">type case2 = IsTuple&lt;readonly [number]&gt; // true</span>
<span class="line">type case3 = IsTuple&lt;number[]&gt; // false</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>答案：</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">type IsTuple&lt;T&gt; = [T] extends [never] </span>
<span class="line">  ? false </span>
<span class="line">  : T extends readonly any[]</span>
<span class="line">    ? number extends T[&#39;length&#39;] ? false : true</span>
<span class="line">    : false</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这里解题的关键在于数组的<code>length</code>是<code>nubmer</code>类型的，而元组的<code>length</code>是一个特殊的固定的数</p><p>这里的<code>[T] extends [never]</code> 也是之前讨论的问题</p><h1 id="trimright" tabindex="-1"><a class="header-anchor" href="#trimright"><span>TrimRight</span></a></h1><p>将字符串右侧的空格去掉</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">type Trimmed = TrimRight&lt;&#39;   Hello World    &#39;&gt; </span>
<span class="line">// expected to be &#39;   Hello World&#39;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>答案</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">// 注意最后有一个空格</span>
<span class="line">type TrimRight&lt;S extends string&gt; = S extends \`\${infer Rest}\${&#39; &#39;}\` </span>
<span class="line">  ? TrimRight&lt;Rest&gt;</span>
<span class="line">  : S</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>但是在测试的例子中存在<code>\\t</code>这种转义字符，我们需要将他们过滤出来</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">type TrimRight&lt;S extends string&gt; = </span>
<span class="line">  S extends \`\${infer Rest}\${ &#39; &#39; | &#39;\\t&#39; | &#39;\\n&#39; }\` </span>
<span class="line">    ? TrimRight&lt;Rest&gt;</span>
<span class="line">    : S</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>也是很经典的递归 + 字符串拼接 + 模式匹配提取</p><h1 id="without" tabindex="-1"><a class="header-anchor" href="#without"><span>WithOut</span></a></h1><p>数组去除指定的元素后再去重</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">type Res = Without&lt;[1, 2], 1&gt;; // expected to be [2]</span>
<span class="line">type Res1 = Without&lt;[1, 2, 4, 1, 5], [1, 2]&gt;; // expected to be [4, 5]</span>
<span class="line">type Res2 = Without&lt;[2, 3, 2, 3, 2, 3, 2, 3], [2, 3]&gt;; // expected to be []</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>答案：</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">type ToUnion&lt;T&gt; = T extends any[] ? T[number] : T</span>
<span class="line">type Without&lt;T, U&gt; = </span>
<span class="line">  T extends [infer R, ...infer F]</span>
<span class="line">    ? R extends ToUnion&lt;U&gt;</span>
<span class="line">      ? Without&lt;F, U&gt;</span>
<span class="line">      : [R, ...Without&lt;F, U&gt;]</span>
<span class="line">    : T</span>
<span class="line">    </span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h1 id="join" tabindex="-1"><a class="header-anchor" href="#join"><span>Join</span></a></h1><div class="language-SQL line-numbers-mode" data-highlighter="prismjs" data-ext="SQL"><pre><code class="language-SQL"><span class="line">type Res = Join&lt;[&quot;a&quot;, &quot;p&quot;, &quot;p&quot;, &quot;l&quot;, &quot;e&quot;], &quot;-&quot;&gt;; // expected to be &#39;a-p-p-l-e&#39;</span>
<span class="line">type Res1 = Join&lt;[&quot;Hello&quot;, &quot;World&quot;], &quot; &quot;&gt;; // expected to be &#39;Hello World&#39;</span>
<span class="line">type Res2 = Join&lt;[&quot;2&quot;, &quot;2&quot;, &quot;2&quot;], 1&gt;; // expected to be &#39;21212&#39;</span>
<span class="line">type Res3 = Join&lt;[&quot;o&quot;], &quot;u&quot;&gt;; // expected to be &#39;o&#39;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>答案 <a href="https://github" target="_blank" rel="noopener noreferrer">https://github</a>.com/type-challenges/type-challenges/issues/14125</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">type Join&lt;T extends string[], U extends string | number&gt; = </span>
<span class="line">  T extends [infer L extends string, ...infer R extends string[]]</span>
<span class="line">    ? R[&#39;length&#39;] extends 0</span>
<span class="line">      ?  L</span>
<span class="line">      : \`\${L}\${U}\${Join&lt;R, U&gt;}\`</span>
<span class="line">    : &#39;&#39;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h1 id="unique" tabindex="-1"><a class="header-anchor" href="#unique"><span>Unique</span></a></h1><p>Implement the type version of Lodash.uniq, Unique takes an Array T, returns the Array T without repeated values.</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">type Res = Unique&lt;[1, 1, 2, 2, 3, 3]&gt;; // expected to be [1, 2, 3]</span>
<span class="line">type Res1 = Unique&lt;[1, 2, 3, 4, 4, 5, 6, 7]&gt;; // expected to be [1, 2, 3, 4, 5, 6, 7]</span>
<span class="line">type Res2 = Unique&lt;[1, &quot;a&quot;, 2, &quot;b&quot;, 2, &quot;a&quot;]&gt;; // expected to be [1, &quot;a&quot;, 2, &quot;b&quot;]</span>
<span class="line">type Res3 = Unique&lt;[string, number, 1, &quot;a&quot;, 1, string, 2, &quot;b&quot;, 2, number]&gt;; // expected to be [string, number, 1, &quot;a&quot;, 2, &quot;b&quot;]</span>
<span class="line">type Res4 = Unique&lt;[unknown, unknown, any, any, never, never]&gt;; // expected to be [unknown, any, never]</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>答案 ，没看懂回学校看<a href="https://github" target="_blank" rel="noopener noreferrer">https://github</a>.com/type-challenges/type-challenges/issues/14151</p><h1 id="constructtuple" tabindex="-1"><a class="header-anchor" href="#constructtuple"><span>ConstructTuple</span></a></h1><p>构造指定长度的元组</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">type result = ConstructTuple&lt;2&gt; // expect to be [unknown, unknown]</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>答案：</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">type ConstructTuple&lt;L extends number, U extends unknown[] = []&gt; = </span>
<span class="line">  U[&#39;length&#39;] extends L</span>
<span class="line">    ? U</span>
<span class="line">    : ConstructTuple&lt;L, [...U, unknown]&gt;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这里使用了<code>U extends unknown[] = []</code>，这样在类型的定义的过程中就可以是使用U了，这个技巧经常出现</p><h1 id="numberrange" tabindex="-1"><a class="header-anchor" href="#numberrange"><span>NumberRange</span></a></h1><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">type NumberRange&lt;</span>
<span class="line">  L, </span>
<span class="line">  H, </span>
<span class="line">  Count extends any[] = [], </span>
<span class="line">  Res extends any[] = [] , </span>
<span class="line">  Flag extends boolean = Count[&#39;length&#39;] extends L ? true : false</span>
<span class="line">&gt; = </span>
<span class="line">  Flag extends true</span>
<span class="line">    ? Count[&#39;length&#39;] extends H</span>
<span class="line">      ? [...Res, Count[&#39;length&#39;]][number]</span>
<span class="line">      : NumberRange&lt;L, H, [...Count, &#39;&#39;], [...Res,  Count[&#39;length&#39;]], Flag&gt;</span>
<span class="line">    : NumberRange&lt;L, H, [...Count, &#39;&#39;]&gt;</span>
<span class="line"></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h1 id="checkrepeatedchars" tabindex="-1"><a class="header-anchor" href="#checkrepeatedchars"><span>CheckRepeatedChars</span></a></h1><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">type CheckRepeatedChars&lt;T extends string&gt; = T extends \`\${infer F}\${infer E}\` </span>
<span class="line">  ? E extends \`\${string}\${F}\${string}\`</span>
<span class="line">    ? true</span>
<span class="line">    : CheckRepeatedChars&lt;E&gt;</span>
<span class="line">  : false</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h1 id="parseurlparams" tabindex="-1"><a class="header-anchor" href="#parseurlparams"><span>ParseUrlParams</span></a></h1><p>将Url转换为联合类型</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">ParseUrlParams&lt;&#39;:id&#39;&gt; // id</span>
<span class="line">ParseUrlParams&lt;&#39;posts/:id&#39;&gt; // id</span>
<span class="line">ParseUrlParams&lt;&#39;posts/:id/:user&#39;&gt; // id | user</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>答案</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">type ParseUrlParams&lt;T&gt; = </span>
<span class="line">  T extends \`\${string}:\${infer R}\` </span>
<span class="line">    ? R extends \`\${infer F}/\${string}\` </span>
<span class="line">      ? F | ParseUrlParams&lt;R&gt; </span>
<span class="line">      : R</span>
<span class="line">    : never</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这道题我最开始也想到使用递归来做，但是没想到如何来构造成Union，我一开始是想要用数组存起来，之后在转为Union，这种做法反而麻烦了</p><h1 id="getmiddleelement" tabindex="-1"><a class="header-anchor" href="#getmiddleelement"><span>GetMiddleElement</span></a></h1><p>获取数组的中间元素</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">type simple1 = GetMiddleElement&lt;[1, 2, 3, 4, 5]&gt;, // expected to be [3]</span>
<span class="line">  type simple2 = GetMiddleElement&lt;[1, 2, 3, 4, 5, 6]&gt; // expected to be [3, 4]</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>答案</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">type GetMiddleElement&lt;T extends any[]&gt; = </span>
<span class="line">  T extends [infer F, ...infer M, infer B ] </span>
<span class="line">    ? M extends [] </span>
<span class="line">      ? [F, B] </span>
<span class="line">      : GetMiddleElement&lt;M&gt; </span>
<span class="line">    : T</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>不断的将两侧的项剔除，直到剩最后的0个（数组偶数项）或1个项（数组奇数项），偶数直接返回其左右的项，奇数返回其本身</p><p>感觉基本上练的差不多了</p><h1 id="协变与逆变" tabindex="-1"><a class="header-anchor" href="#协变与逆变"><span>协变与逆变</span></a></h1><p><a href="https://github" target="_blank" rel="noopener noreferrer">https://github</a>.com/shfshanyue/Daily-Question/issues/713</p><p>TypeScript 逆变和协变 &amp;gt; 文章中所有的代码均在这里 <a href="https://www.typescriptlang.org/play?#-QFJWTFUEQ3z+YAcLI5GC-GjfH5tHHIPFwgnwm6EPF-MpkoA" target="_blank" rel="noopener noreferrer">TS Playground - An online editor for exploring TypeScript and JavaScript</a> ## 一些概念 ### Subtyping 子类型 在编程语言理论中，子类型是一种类型多态的形式，这种类型可以替换其超类型(supertype)。如果 S 是 T 的子类型，一般表示为 S &amp;lt;: T，意思是在任何类型为 T 的地方都可以安全的使用 S。 <code>js type T = number type S = T | string type Fn = (arg: T) =&amp;gt; void let fn: Fn = (arg: S) =&amp;gt; {} </code> 上面的代码我们定义了 T 和 S 类型，然后定义了一个 参数为 T 返回值为 any 的函数类型 Fn， 但是在具体的赋值的时候我们将 args 变为 S，程序是可以正常运行的。 ### 协变与逆变 &amp;gt; 协变与逆变（Covariance and contravariance）是在计算机科学中，描述具有父/子型别关系的多个型别通过型别构造器、构造出的多个复杂型别之间是否有父/子型别关系的用语。 在一门程序设计语言的<a href="https://zh.wikipedia.org/wiki/%E5%9E%8B%E5%88%A5%E7%B3%BB%E7%B5%B1" target="_blank" rel="noopener noreferrer">类型系统</a>中，一个类型规则或者类型构造器是： - 协变（covariant），如果它保持了<a href="https://zh.wikipedia.org/wiki/%E5%AD%90%E5%9E%8B%E5%88%A5" target="_blank" rel="noopener noreferrer">子类型序关系≦</a>。该序关系是：子类型≦基类型。 - 逆变（contravariant），如果它逆转了子类型序关系。 - 不变（invariant），如果上述两种均不适用。 维基百科中的描述有点抽象，我们提取一下关键词 - 父/子型别 - 构造器构造 - 是否具有父/子型别关系 我们先用简单的数学模拟一下，假设我们现在有两个值 x = -1 ， y = -5，x 和 y 的关系为 x &amp;gt; y。 假设现在有函数 $f(t) = t + 10$ 将我们的 x 和 y 代入 f(t) 后得到 f(x) = 9 和 f(y) = 5 ，可以发现 f(x) 和 f(y) 的关系仍然为 f(x) &amp;gt; f(y)，这就是典型的协变。 假设如下函数 $g(t) = t^2$ g(x) = 1 &amp;lt; g(y) = 5 这就是逆变。 上面只是举了一个很简单并且不够严谨的例子，主要是为了方便理解，现在我们看一下在 ts 中的实现。 ### TypeScript实现 考虑如下类型 <code>js dinterface Animal { name: string } interface Dog extends Animal { // 摇尾巴 waggingTail(): void } interface Corgi extends Dog { canWagging: false } </code> 代码中我们定义了三个类型，他们之间的子集关系为 Corgi &amp;lt;: Dog &amp;lt;: Animal。 <code>js // 协变 type AnimalList = Array&amp;lt;Animal&amp;gt; type DogList = Array&amp;lt;Dog&amp;gt; let animalArr: AnimalList = []; let dogArr: DogList = []; // ✅ DogList 为 AnimalList 子集 animalArr = dogArr; </code> 我们再考虑一种特殊情况 <code>js type Fn1 = (arg: Dog) =&amp;gt; Dog </code> Fn1 类型的子类型是什么呢？ 是 (arg: Corgi) =&amp;gt; Corgi吗？ 考虑如下场景 !<a href="https://user-images.githubusercontent.com/73587626/207111255-346a9f4b-22ae-4f8b-939d-1429b95888cc.png" target="_blank" rel="noopener noreferrer">image</a> 显然 Fn3 并不是 Fn1 的子类型。 我们分析一下这样为什么不被允许，由于 Fn3 类型的限制，这里 fn3 函数的参数只能传入 arg 为 Corgi 类型的函数，但是本来的 Fn1 是允许任何 Dog 类型的参数，所以 ts 禁止了这样的操作。 所以 Fn1 的子类型应该为参数可以接受任何类型的 Dog，返回值具有 Dog 所有值的类型。 所以正确答案是 (arg: Animal) =&amp;gt; Corgi 。 !<a href="https://user-images.githubusercontent.com/73587626/207111384-9e00ad55-266f-4149-b487-60530555a103.png" target="_blank" rel="noopener noreferrer">image</a> &amp;gt; 为了方便表示，这里我们定义 A → B 指的是以 A 为参数类型，以 B 为返回值类型的函数类型。 返回值类型很容易理解：柯基是狗的子类型。但参数类型则是相反的：动物是狗的父类。 用合适的术语来描述这个奇怪的表现，可以说我们允许一个函数类型中，返回值类型是协变的，而参数类型是逆变的。返回值类型是协变的，意思是 A &amp;lt;: B 就意味着 (T → A) &amp;lt;: (T → B) 。参数类型是逆变的，意思是 A &amp;lt;: B 就意味着 (B → T) &amp;lt;: (A → T) （ A 和 B 的位置颠倒过来了）。 一个有趣的现象：在 TypeScript 中， <a href="https://github.com/Microsoft/TypeScript/wiki/FAQ#why-are-function-parameters-bivariant" target="_blank" rel="noopener noreferrer">参数类型是双向协变的</a> ，也就是说既是协变又是逆变的，而这并不安全。但是现在你可以在 <a href="https://www.typescriptlang.org/docs/handbook/release-notes/typescript-2-6.html" target="_blank" rel="noopener noreferrer">TypeScript 2.6</a> 版本中通过 --strictFunctionTypes 或 --strict 标记来修复这个问题。 参考 - <a href="https://zh.wikipedia.org/wiki/%E5%AD%90%E7%B1%BB%E5%9E%8B" target="_blank" rel="noopener noreferrer">维基百科-子类型</a> - <a href="https://zh.wikipedia.org/wiki/%E5%8D%8F%E5%8F%98%E4%B8%8E%E9%80%86%E5%8F%98#%E2%80%9C%E5%8D%8F%E5%8F%98%E2%80%9D%E4%B8%80%E8%AF%8D%E7%9A%84%E6%9D%A5%E6%BA%90" target="_blank" rel="noopener noreferrer">维基百科-协变与逆变</a> - <a href="https://www.stephanboyer.com/post/132/what-are-covariance-and-contravariance" target="_blank" rel="noopener noreferrer">What are covariance and contravariance? | Stephan Boyer</a></p><h2 id="一、核心问题-什么是协变和逆变" tabindex="-1"><a class="header-anchor" href="#一、核心问题-什么是协变和逆变"><span>一、核心问题：什么是协变和逆变？</span></a></h2><p>Stephan Boyer 文章的核心思路是：<strong>当我们有一个简单的类型关系时（比如 Dog &amp;lt;: Animal），把这些类型&quot;塞进&quot;更复杂的类型构造器（如数组、函数）之后，这个父子关系会怎么变化？</strong></p><p>这就引出三种可能：</p><table><thead><tr><th>变化情况</th><th>含义</th><th>例子</th></tr></thead><tbody><tr><td><strong>协变 (Covariant)</strong></td><td>子类型关系<strong>保持</strong>方向不变</td><td><code>Dog &amp;lt;: Animal</code> → <code>Array&amp;lt;Dog&amp;gt; &amp;lt;: Array&amp;lt;Animal&amp;gt;</code></td></tr><tr><td><strong>逆变 (Contravariant)</strong></td><td>子类型关系<strong>反转</strong>方向</td><td><code>Dog &amp;lt;: Animal</code> → <code>(Animal → T) &amp;lt;: (Dog → T)</code></td></tr><tr><td><strong>不变 (Invariant)</strong></td><td>两个方向都不成立</td><td>可变数组在某些语言中是不变的</td></tr></tbody></table><hr><h2 id="二、为什么返回值是协变的" tabindex="-1"><a class="header-anchor" href="#二、为什么返回值是协变的"><span>二、为什么返回值是协变的？</span></a></h2><p>这部分比较直觉。Boyer 的解释是：</p><p>&gt; 如果我期望一个函数返回 <code>Animal</code>，而你给我的函数实际返回 <code>Dog</code>——这完全可以，因为 Dog 本身就是 Animal 的一种。所有对 Animal 的操作对 Dog 都是合法的。 &gt; &gt;</p><p>用你文章的例子：</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">type Fn1 = (arg: Dog) =&gt; Dog</span>
<span class="line"></span>
<span class="line">// 返回值 Corgi &lt;: Dog，所以协变成立</span>
<span class="line">let fn: Fn1 = (arg: Dog): Corgi =&gt; ({ name: &#39;corgi&#39;, waggingTail() {}, canWagging: false })</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>返回值是&quot;输出&quot;位置</strong>——调用者拿到返回值后去使用它。返回一个更具体的子类型，调用者完全可以把它当作父类型用，毫无风险。</p><hr><h2 id="三、为什么参数是逆变的-重点-难点" tabindex="-1"><a class="header-anchor" href="#三、为什么参数是逆变的-重点-难点"><span>三、为什么参数是逆变的？（重点 &amp; 难点）</span></a></h2><p>这是最反直觉的部分。Boyer 用了一个非常精炼的推理：</p><h3 id="思考方式-站在-调用者-的角度" tabindex="-1"><a class="header-anchor" href="#思考方式-站在-调用者-的角度"><span>思考方式：站在&quot;调用者&quot;的角度</span></a></h3><p>假设你声明了一个变量 <code>fn: (arg: Dog) =&amp;gt; void</code>，这意味着<strong>调用者有权传入任何 Dog</strong>（包括 Corgi、Husky 等等）。</p><p>现在问：什么样的函数可以安全地赋值给 <code>fn</code>？</p><p>**情况 1：赋值一个 **<strong><code>(arg: Corgi) =&amp;gt; void</code></strong></p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">type Fn1 = (arg: Dog) =&gt; void</span>
<span class="line">type Fn3 = (arg: Corgi) =&gt; void</span>
<span class="line"></span>
<span class="line">let fn: Fn1 = fn3 // ❌ 不安全！</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>为什么不安全？因为：</p><ul><li><p>调用者认为 <code>fn</code> 接受任何 <code>Dog</code></p></li><li><p>调用者传入一个 <code>Husky</code>（Husky 也是 Dog）</p></li><li><p>但 <code>fn3</code> 内部只处理 <code>Corgi</code>，它可能会访问 <code>canWagging</code> 属性</p></li><li><p><code>Husky</code> 没有 <code>canWagging</code> → <strong>运行时崩溃！</strong></p></li></ul><p>**情况 2：赋值一个 **<strong><code>(arg: Animal) =&amp;gt; void</code></strong></p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">type Fn1 = (arg: Dog) =&gt; void</span>
<span class="line">type Fn2 = (arg: Animal) =&gt; void</span>
<span class="line"></span>
<span class="line">let fn: Fn1 = fn2 // ✅ 安全！</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>为什么安全？因为：</p><ul><li><p>调用者传入任何 <code>Dog</code></p></li><li><p><code>fn2</code> 能处理任何 <code>Animal</code>，而 Dog &amp;lt;: Animal，所以 Dog 肯定能被 <code>fn2</code> 正确处理</p></li><li><p><strong>参数处理能力更&quot;宽泛&quot;的函数，反而是子类型</strong></p></li></ul><h3 id="用一句话总结" tabindex="-1"><a class="header-anchor" href="#用一句话总结"><span>用一句话总结</span></a></h3><p>&gt; <strong>参数是&quot;输入&quot;位置——能接受更多类型的函数更安全，所以函数参数类型是逆变的。</strong> &gt; &gt;</p><p>这就是 Boyer 文章的核心洞见：</p><table><thead><tr><th>位置</th><th>角色</th><th>变型</th><th>直觉</th></tr></thead><tbody><tr><td>返回值</td><td>输出（Producer）</td><td><strong>协变</strong></td><td>给你更具体的东西，你总能用</td></tr><tr><td>参数</td><td>输入（Consumer）</td><td><strong>逆变</strong></td><td>能吃更多种类的食物，说明兼容性更强</td></tr></tbody></table><hr><h2 id="四、组合规则" tabindex="-1"><a class="header-anchor" href="#四、组合规则"><span>四、组合规则</span></a></h2><p>Boyer 进一步总结了<strong>函数类型的完整子类型规则</strong>：</p><p>如果 <code>A &amp;lt;: B</code> 且 <code>C &amp;lt;: D</code>，那么：</p><p>$(B \\to C) &lt;: (A \\to D)$</p><p>翻译成人话：</p><ul><li><p><strong>参数类型反过来</strong>（B 是 A 的父类型 → 逆变）</p></li><li><p><strong>返回值类型跟着走</strong>（C 是 D 的子类型 → 协变）</p></li></ul><p>对应你文章中的结论：</p><div class="language-Plain line-numbers-mode" data-highlighter="prismjs" data-ext="Plain"><pre><code class="language-Plain"><span class="line">Dog &lt;: Animal，Corgi &lt;: Dog</span>
<span class="line"></span>
<span class="line">所以 (Animal → Corgi) &lt;: (Dog → Dog)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>完美验证。</p><hr><h2 id="五、typescript-的特殊处理" tabindex="-1"><a class="header-anchor" href="#五、typescript-的特殊处理"><span>五、TypeScript 的特殊处理</span></a></h2><p>你文章最后提到的双向协变（Bivariance）是 TypeScript 的一个<strong>实用主义妥协</strong>：</p><ul><li><p><strong>理论上</strong>，参数应该严格逆变</p></li><li><p><strong>实际中</strong>，TypeScript 2.6 之前默认参数是<strong>双向协变</strong>的（既允许子类型也允许父类型），因为这样在 DOM 事件回调等常见场景下更方便</p></li><li><p><strong><code>--strictFunctionTypes</code></strong> 修复了这个问题，让函数参数回归严格的逆变检查</p></li></ul><p>但要注意：<strong>方法（method shorthand）声明仍然是双向协变的</strong>，只有用箭头函数/函数表达式声明的才会严格逆变：</p><div class="language-TypeScript line-numbers-mode" data-highlighter="prismjs" data-ext="TypeScript"><pre><code class="language-TypeScript"><span class="line">interface Example {</span>
<span class="line">  method(arg: Dog): void       // 双向协变（宽松）</span>
<span class="line">  arrow: (arg: Dog) =&gt; void    // 严格逆变（--strict下）</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="六、总结口诀" tabindex="-1"><a class="header-anchor" href="#六、总结口诀"><span>六、总结口诀</span></a></h2><p>记住一个简单的模型：</p><p>&gt; <strong>函数是&quot;吃参数、吐返回值&quot;的机器。</strong> &gt; &gt; - <strong>吐出来的</strong>（返回值）→ 可以更具体 → <strong>协变</strong> &gt; &gt; - <strong>吃进去的</strong>（参数）→ 要能吃更多 → <strong>逆变</strong> &gt; &gt;</p><p>希望这个解读让 Boyer 那篇文章的思路变得更清晰了。如果你对某个具体点还有疑问，随时可以继续讨论。</p>`,195)])])}const d=n(l,[["render",t]]),c=JSON.parse('{"path":"/notes/obsidian/%E5%89%8D%E7%AB%AF/%E5%B7%A5%E7%A8%8B%E5%8C%96/%E7%B1%BB%E5%9E%8B%E6%A3%80%E6%9F%A5/TS/%E7%B1%BB%E5%9E%8B%E4%BD%93%E6%93%8D/%E7%B1%BB%E5%9E%8B%E4%BD%93%E6%93%8D-%E5%AE%9E%E4%B9%A0.html","title":"类型体操-实习","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"notes/obsidian/前端/工程化/类型检查/TS/类型体操/类型体操-实习.md"}');export{d as comp,c as data};
